import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Feature {
  id: string;
  title: string;
  description: string;
  icon: string;
}

export interface Testimonial {
  id: string;
  name: string;
  role: string;
  content: string;
  avatar: string;
}

export interface FAQItem {
  id: string;
  question: string;
  answer: string;
}

export interface Message {
  role: 'user' | 'assistant';
  content: string;
}

import { GoogleGenAI } from "@google/genai";

const SYSTEM_INSTRUCTION = `
You are a friendly AI Sales Assistant for "Luminary", a premium productivity mobile app.
Your goal is to answer visitor questions about the app's features:
- Focus Mode: Blocks distractions and uses deep work timers.
- Smart Insights: Weekly AI summaries of how you spent your time.
- Cloud Sync: Works seamlessly across iOS, Android, and Web.
- Collaborative Tasks: Share lists and projects with teams.
Pricing: Luminary is free to start, with a Pro plan at $4.99/mo for advanced insights and unlimited cloud storage.
Be concise, professional, and enthusiastic.
If asked about downloads, direct them to use the "Download Now" buttons in the navigation.
`;

export const getAssistantResponse = async (userPrompt: string) => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: userPrompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
      },
    });
    return response.text || "I'm sorry, I couldn't process that request right now. How else can I help you with Luminary?";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Something went wrong. Please check your connection or try again later.";
  }
};

import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import Features from './components/Features';
import About from './components/About';
import Testimonials from './components/Testimonials';
import FAQ from './components/FAQ';
import Contact from './components/Contact';
import Footer from './components/Footer';
import AIChatBot from './components/AIChatBot';

const App: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div className="min-h-screen flex flex-col">
      <Header isScrolled={isScrolled} />

      <main className="flex-grow">
        <section id="home">
          <Hero />
        </section>

        <section id="features" className="py-20 bg-white">
          <Features />
        </section>

        <section id="about" className="py-20 bg-slate-50">
          <About />
        </section>

        <section id="testimonials" className="py-20 bg-white">
          <Testimonials />
        </section>

        <section id="faq" className="py-20 bg-slate-50">
          <FAQ />
        </section>

        <section id="contact" className="py-20 bg-white">
          <Contact />
        </section>
      </main>

      <Footer />
      <AIChatBot />
    </div>
  );
};

export default App;

